// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 rollNum, uint256 ts) public {
        vm.assume(caller != address(0));
        rollNum = bound(rollNum, 1, 1_000_000_000);
        ts = bound(ts, block.timestamp + 1, block.timestamp + 10_000_000);

        vm.deal(caller, 20 ether);

        vm.roll(rollNum);
        vm.warp(ts);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        vm.assume(ok);

        bool drained = address(c).balance == 0;
        bool cond = (block.number % 15) == 0;
        assertTrue(drained == cond);
    }
}
